//! Source fixtures from tests/api/test_proxy_authorization_matrix.py and
//! test_proxy_rate_limit_behavior.py. These test real native policy/limiter
//! implementations with in-memory state; they do not claim DB/JWT HTTP coverage.
use ai_platform_gateway::{service_access_policy::{ServiceAccessConstraints,service_access_policy_from_metadata,service_visible_with_scopes},rate_policy_store::{PolicyContext,RatePolicyResolver,RuntimeRateRules,ServiceRatePolicy},rate_limits::{RateLimitContext,RatePolicy,SlidingWindowRateLimiter},migration_compat::transparent_proxy::detect_operation};
use ai_platform_auth::rbac::{Rbac,Capability,check_capability,permission_denied_detail};
use serde_json::{Value,json};
use std::{sync::Arc,collections::HashMap};
fn visible(user_policy:Value,sources:Vec<(String,Vec<String>)>,admin:bool)->bool {let c=ServiceAccessConstraints{allowed_sources:sources,user_policy:service_access_policy_from_metadata(&json!({"service_access":user_policy}))};service_visible_with_scopes(&[json!("agent")],&c.allowed_sources,&c.user_policy,admin)}
#[test] fn expected_roles_have_agent_invoke_capability(){let roles=["user","manager","cs_staff","sales_staff","admin"];let rbac=Rbac::new(roles.iter().map(|r|(r.to_string(),vec!["conversation:playground:access".into()])).collect::<HashMap<_,_>>());for role in roles{assert!(check_capability(&rbac,&[role.into()],&[],Capability::AgentInvoke).allowed());}}
#[test] fn guest_denial_identifies_required_capability(){let rbac=Rbac::default();assert!(!check_capability(&rbac,&["guest".into()],&[],Capability::AgentInvoke).allowed());let body=permission_denied_detail(Capability::AgentInvoke,"req-test-001",None);assert_eq!(body["required_capability"],"AgentInvoke");assert_eq!(body["required_permission"],"conversation:playground:access");}
#[test] fn user_allowlist_blocks_unmatched_service(){assert!(!visible(json!({"mode":"allowlist","allowed_services":["flash"]}),vec![],false));}
#[test] fn user_allowlist_accepts_match(){assert!(visible(json!({"mode":"allowlist","allowed_services":["agent"]}),vec![],false));}
#[test] fn user_denylist_precedes_allowlist(){assert!(!visible(json!({"mode":"all","denied_services":["agent"]}),vec![],false));assert!(!visible(json!({"mode":"allowlist","allowed_services":["agent"],"denied_services":["agent"]}),vec![],false));}
#[test] fn api_key_allowed_services_is_intersection(){assert!(!visible(json!({}),vec![("api_key".into(),vec!["flash".into()])],false));assert!(!visible(json!({}),vec![("api_key".into(),vec!["agent".into()]),("tenant".into(),vec!["flash".into()])],false));}
#[test] fn admin_bypasses_only_user_policy(){assert!(visible(json!({"mode":"allowlist","allowed_services":[]}),vec![],true));assert!(!visible(json!({}),vec![("api_key".into(),vec!["flash".into()])],true));}
fn context()->PolicyContext{PolicyContext{actor:RateLimitContext{ip:"127.0.0.1".into(),user_id:Some("user_1".into()),tenant_id:Some("tenant_1".into()),user_tier:"normal".into(),assistant_id:Some("agent".into()),operation:Some("run_wait".into())},service_name:"agent".into(),..Default::default()}}
#[tokio::test] async fn service_override_takes_precedence(){let resolver=RatePolicyResolver::new(Arc::new(RuntimeRateRules::new(vec![json!({"scope":"global","requests":60,"window":60,"enabled":true})])));let policies=resolver.resolve(&context(),Some(&ServiceRatePolicy{enabled:true,requests:5,window:60,service_id:"agent".into()})).await.unwrap();assert_eq!(policies.len(),1);assert_eq!(policies[0].requests,5);assert_eq!(policies[0].dimension,"service:agent");assert!(policies[0].key.contains("tenant_1:user_1:run_wait"));}
#[tokio::test] async fn disabled_service_override_uses_global_rule(){let resolver=RatePolicyResolver::new(Arc::new(RuntimeRateRules::new(vec![json!({"scope":"global","requests":60,"window":60,"enabled":true})])));let policies=resolver.resolve(&context(),Some(&ServiceRatePolicy{enabled:false,requests:5,window:60,service_id:"agent".into()})).await.unwrap();assert_eq!(policies.len(),1);assert_eq!(policies[0].requests,60);assert_eq!(policies[0].dimension,"global");}
#[tokio::test] async fn real_memory_rate_limit_rejects_at_configured_limit(){let limiter=SlidingWindowRateLimiter::new(None);let policies=[RatePolicy::new("service:agent","service:agent",5,60)];for _ in 0..5{assert!(limiter.check_custom_limits_at(&policies,100.0).await.unwrap()[0].allowed);}let result=limiter.check_custom_limits_at(&policies,100.0).await.unwrap().remove(0);assert!(!result.allowed);assert_eq!(result.limit,5);assert_eq!(result.remaining,0);assert!(result.retry_after>0);assert!(result.headers().contains_key("Retry-After"));}
#[test] fn source_operation_mapping_for_run_and_thread_paths(){assert_eq!(detect_operation("POST","threads/t/runs/stream/"),"run_stream");assert_eq!(detect_operation("POST","runs/wait"),"run_wait");assert_eq!(detect_operation("GET","threads/t/state"),"thread_read");}
